_bdf_parse_glyphs( char*          line,
                   unsigned long  linelen,
                   unsigned long  lineno,
                   void*          call_data,
                   void*          client_data )
{
  int                c, mask_index;
  char*              s;
  unsigned char*     bp;
  unsigned long      i, slen, nibbles;

  _bdf_parse_t*      p;
  bdf_glyph_t*       glyph;
  bdf_font_t*        font;

  FT_Memory          memory;
  FT_Error           error = BDF_Err_Ok;

  FT_UNUSED( call_data );
  FT_UNUSED( lineno );        /* only used in debug mode */


  p = (_bdf_parse_t *)client_data;

  font   = p->font;
  memory = font->memory;

  /* Check for a comment. */
  if ( ft_memcmp( line, "COMMENT", 7 ) == 0 )
  {
    linelen -= 7;

    s = line + 7;
    if ( *s != 0 )
    {
      s++;
      linelen--;
    }
    error = _bdf_add_comment( p->font, s, linelen );
    goto Exit;
  }

  /* The very first thing expected is the number of glyphs. */
  if ( !( p->flags & _BDF_GLYPHS ) )
  {
    if ( ft_memcmp( line, "CHARS", 5 ) != 0 )
    {
      FT_ERROR(( "_bdf_parse_glyphs: " ERRMSG1, lineno, "CHARS" ));
      error = BDF_Err_Missing_Chars_Field;
      goto Exit;
    }

    error = _bdf_list_split( &p->list, (char *)" +", line, linelen );
    if ( error )
      goto Exit;
    p->cnt = font->glyphs_size = _bdf_atoul( p->list.field[1], 0, 10 );

    /* Make sure the number of glyphs is non-zero. */
    if ( p->cnt == 0 )
      font->glyphs_size = 64;

    /* Limit ourselves to 1,114,112 glyphs in the font (this is the */
    /* number of code points available in Unicode).                 */
    if ( p->cnt >= 0x110000UL )
    {
      FT_ERROR(( "_bdf_parse_glyphs: " ERRMSG5, lineno, "CHARS" ));
      error = BDF_Err_Invalid_Argument;
      goto Exit;
    }

    if ( FT_NEW_ARRAY( font->glyphs, font->glyphs_size ) )
      goto Exit;

    p->flags |= _BDF_GLYPHS;

    goto Exit;
  }

  /* Check for the ENDFONT field. */
  if ( ft_memcmp( line, "ENDFONT", 7 ) == 0 )
  {
    /* Sort the glyphs by encoding. */
    ft_qsort( (char *)font->glyphs,
              font->glyphs_used,
              sizeof ( bdf_glyph_t ),
              by_encoding );

    p->flags &= ~_BDF_START;

    goto Exit;
  }

  /* Check for the ENDCHAR field. */
  if ( ft_memcmp( line, "ENDCHAR", 7 ) == 0 )
  {
    p->glyph_enc = 0;
    p->flags    &= ~_BDF_GLYPH_BITS;

    goto Exit;
  }

  /* Check whether a glyph is being scanned but should be */
  /* ignored because it is an unencoded glyph.            */
  if ( ( p->flags & _BDF_GLYPH )     &&
       p->glyph_enc            == -1 &&
       p->opts->keep_unencoded == 0  )
    goto Exit;

  /* Check for the STARTCHAR field. */
  if ( ft_memcmp( line, "STARTCHAR", 9 ) == 0 )
  {
    /* Set the character name in the parse info first until the */
    /* encoding can be checked for an unencoded character.      */
    FT_FREE( p->glyph_name );

    error = _bdf_list_split( &p->list, (char *)" +", line, linelen );
    if ( error )
      goto Exit;

    _bdf_list_shift( &p->list, 1 );

    s = _bdf_list_join( &p->list, ' ', &slen );

    if ( !s )
    {
      FT_ERROR(( "_bdf_parse_glyphs: " ERRMSG8, lineno, "STARTCHAR" ));
      error = BDF_Err_Invalid_File_Format;
      goto Exit;
    }

    if ( FT_NEW_ARRAY( p->glyph_name, slen + 1 ) )
      goto Exit;

    FT_MEM_COPY( p->glyph_name, s, slen + 1 );

    p->flags |= _BDF_GLYPH;

    FT_TRACE4(( DBGMSG1, lineno, s ));

    goto Exit;
  }

  /* Check for the ENCODING field. */
  if ( ft_memcmp( line, "ENCODING", 8 ) == 0 )
  {
    if ( !( p->flags & _BDF_GLYPH ) )
    {
      /* Missing STARTCHAR field. */
      FT_ERROR(( "_bdf_parse_glyphs: " ERRMSG1, lineno, "STARTCHAR" ));
      error = BDF_Err_Missing_Startchar_Field;
      goto Exit;
    }

    error = _bdf_list_split( &p->list, (char *)" +", line, linelen );
    if ( error )
      goto Exit;

    p->glyph_enc = _bdf_atol( p->list.field[1], 0, 10 );

    /* Normalize negative encoding values.  The specification only */
    /* allows -1, but we can be more generous here.                */
    if ( p->glyph_enc < -1 )
      p->glyph_enc = -1;

    /* Check for alternative encoding format. */
    if ( p->glyph_enc == -1 && p->list.used > 2 )
      p->glyph_enc = _bdf_atol( p->list.field[2], 0, 10 );

    FT_TRACE4(( DBGMSG2, p->glyph_enc ));

     /* Check that the encoding is in the Unicode range because  */
     /* otherwise p->have (a bitmap with static size) overflows. */
    if ( p->glyph_enc > 0                               &&
         (size_t)p->glyph_enc >= sizeof ( p->have ) * 8 )
     {
       FT_ERROR(( "_bdf_parse_glyphs: " ERRMSG5, lineno, "ENCODING" ));
       error = BDF_Err_Invalid_File_Format;
    }

    /* Check whether this encoding has already been encountered. */
    /* If it has then change it to unencoded so it gets added if */
    /* indicated.                                                */
    if ( p->glyph_enc >= 0 )
    {
      if ( _bdf_glyph_modified( p->have, p->glyph_enc ) )
      {
        /* Emit a message saying a glyph has been moved to the */
        /* unencoded area.                                     */
        FT_TRACE2(( "_bdf_parse_glyphs: " ACMSG12,
                    p->glyph_enc, p->glyph_name ));
        p->glyph_enc = -1;
        font->modified = 1;
      }
      else
        _bdf_set_glyph_modified( p->have, p->glyph_enc );
    }

    if ( p->glyph_enc >= 0 )
    {
      /* Make sure there are enough glyphs allocated in case the */
      /* number of characters happen to be wrong.                */
      if ( font->glyphs_used == font->glyphs_size )
      {
        if ( FT_RENEW_ARRAY( font->glyphs,
                             font->glyphs_size,
                             font->glyphs_size + 64 ) )
          goto Exit;

        font->glyphs_size += 64;
      }

      glyph           = font->glyphs + font->glyphs_used++;
      glyph->name     = p->glyph_name;
      glyph->encoding = p->glyph_enc;

      /* Reset the initial glyph info. */
      p->glyph_name = 0;
    }
    else
    {
      /* Unencoded glyph.  Check whether it should */
      /* be added or not.                          */
      if ( p->opts->keep_unencoded != 0 )
      {
        /* Allocate the next unencoded glyph. */
        if ( font->unencoded_used == font->unencoded_size )
        {
          if ( FT_RENEW_ARRAY( font->unencoded ,
                               font->unencoded_size,
                               font->unencoded_size + 4 ) )
            goto Exit;

          font->unencoded_size += 4;
        }

        glyph           = font->unencoded + font->unencoded_used;
        glyph->name     = p->glyph_name;
        glyph->encoding = font->unencoded_used++;
      }
      else
        /* Free up the glyph name if the unencoded shouldn't be */
        /* kept.                                                */
        FT_FREE( p->glyph_name );

      p->glyph_name = 0;
    }

    /* Clear the flags that might be added when width and height are */
    /* checked for consistency.                                      */
    p->flags &= ~( _BDF_GLYPH_WIDTH_CHECK | _BDF_GLYPH_HEIGHT_CHECK );

    p->flags |= _BDF_ENCODING;

    goto Exit;
  }

  /* Point at the glyph being constructed. */
  if ( p->glyph_enc == -1 )
    glyph = font->unencoded + ( font->unencoded_used - 1 );
  else
    glyph = font->glyphs + ( font->glyphs_used - 1 );

  /* Check whether a bitmap is being constructed. */
  if ( p->flags & _BDF_BITMAP )
  {
    /* If there are more rows than are specified in the glyph metrics, */
    /* ignore the remaining lines.                                     */
    if ( p->row >= (unsigned long)glyph->bbx.height )
    {
      if ( !( p->flags & _BDF_GLYPH_HEIGHT_CHECK ) )
      {
        FT_TRACE2(( "_bdf_parse_glyphs: " ACMSG13, glyph->encoding ));
        p->flags |= _BDF_GLYPH_HEIGHT_CHECK;
        font->modified = 1;
      }

      goto Exit;
    }

    /* Only collect the number of nibbles indicated by the glyph     */
    /* metrics.  If there are more columns, they are simply ignored. */
    nibbles = glyph->bpr << 1;
    bp      = glyph->bitmap + p->row * glyph->bpr;

    for ( i = 0; i < nibbles; i++ )
    {
      c = line[i];
      if ( !sbitset( hdigits, c ) )
        break;
      *bp = (FT_Byte)( ( *bp << 4 ) + a2i[c] );
      if ( i + 1 < nibbles && ( i & 1 ) )
        *++bp = 0;
    }

    /* If any line has not enough columns,            */
    /* indicate they have been padded with zero bits. */
    if ( i < nibbles                            &&
         !( p->flags & _BDF_GLYPH_WIDTH_CHECK ) )
    {
      FT_TRACE2(( "_bdf_parse_glyphs: " ACMSG16, glyph->encoding ));
      p->flags       |= _BDF_GLYPH_WIDTH_CHECK;
      font->modified  = 1;
    }

    /* Remove possible garbage at the right. */
    mask_index = ( glyph->bbx.width * p->font->bpp ) & 7;
    if ( glyph->bbx.width )
      *bp &= nibble_mask[mask_index];

    /* If any line has extra columns, indicate they have been removed. */
    if ( i == nibbles                           &&
         sbitset( hdigits, line[nibbles] )      &&
         !( p->flags & _BDF_GLYPH_WIDTH_CHECK ) )
    {
      FT_TRACE2(( "_bdf_parse_glyphs: " ACMSG14, glyph->encoding ));
      p->flags       |= _BDF_GLYPH_WIDTH_CHECK;
      font->modified  = 1;
    }

    p->row++;
    goto Exit;
  }

  /* Expect the SWIDTH (scalable width) field next. */
  if ( ft_memcmp( line, "SWIDTH", 6 ) == 0 )
  {
    if ( !( p->flags & _BDF_ENCODING ) )
      goto Missing_Encoding;

    error = _bdf_list_split( &p->list, (char *)" +", line, linelen );
    if ( error )
      goto Exit;

    glyph->swidth = (unsigned short)_bdf_atoul( p->list.field[1], 0, 10 );
    p->flags |= _BDF_SWIDTH;

    goto Exit;
  }

  /* Expect the DWIDTH (scalable width) field next. */
  if ( ft_memcmp( line, "DWIDTH", 6 ) == 0 )
  {
    if ( !( p->flags & _BDF_ENCODING ) )
      goto Missing_Encoding;

    error = _bdf_list_split( &p->list, (char *)" +", line, linelen );
    if ( error )
      goto Exit;

    glyph->dwidth = (unsigned short)_bdf_atoul( p->list.field[1], 0, 10 );

    if ( !( p->flags & _BDF_SWIDTH ) )
    {
      /* Missing SWIDTH field.  Emit an auto correction message and set */
      /* the scalable width from the device width.                      */
      FT_TRACE2(( "_bdf_parse_glyphs: " ACMSG9, lineno ));

      glyph->swidth = (unsigned short)FT_MulDiv(
                        glyph->dwidth, 72000L,
                        (FT_Long)( font->point_size *
                                   font->resolution_x ) );
    }

    p->flags |= _BDF_DWIDTH;
    goto Exit;
  }

  /* Expect the BBX field next. */
  if ( ft_memcmp( line, "BBX", 3 ) == 0 )
  {
    if ( !( p->flags & _BDF_ENCODING ) )
      goto Missing_Encoding;

    error = _bdf_list_split( &p->list, (char *)" +", line, linelen );
    if ( error )
      goto Exit;

    glyph->bbx.width    = _bdf_atos( p->list.field[1], 0, 10 );
    glyph->bbx.height   = _bdf_atos( p->list.field[2], 0, 10 );
    glyph->bbx.x_offset = _bdf_atos( p->list.field[3], 0, 10 );
    glyph->bbx.y_offset = _bdf_atos( p->list.field[4], 0, 10 );

    /* Generate the ascent and descent of the character. */
    glyph->bbx.ascent  = (short)( glyph->bbx.height + glyph->bbx.y_offset );
    glyph->bbx.descent = (short)( -glyph->bbx.y_offset );

    /* Determine the overall font bounding box as the characters are */
    /* loaded so corrections can be done later if indicated.         */
    p->maxas    = (short)FT_MAX( glyph->bbx.ascent, p->maxas );
    p->maxds    = (short)FT_MAX( glyph->bbx.descent, p->maxds );

    p->rbearing = (short)( glyph->bbx.width + glyph->bbx.x_offset );

    p->maxrb    = (short)FT_MAX( p->rbearing, p->maxrb );
    p->minlb    = (short)FT_MIN( glyph->bbx.x_offset, p->minlb );
    p->maxlb    = (short)FT_MAX( glyph->bbx.x_offset, p->maxlb );

    if ( !( p->flags & _BDF_DWIDTH ) )
    {
      /* Missing DWIDTH field.  Emit an auto correction message and set */
      /* the device width to the glyph width.                           */
      FT_TRACE2(( "_bdf_parse_glyphs: " ACMSG10, lineno ));
      glyph->dwidth = glyph->bbx.width;
    }

    /* If the BDF_CORRECT_METRICS flag is set, then adjust the SWIDTH */
    /* value if necessary.                                            */
    if ( p->opts->correct_metrics != 0 )
    {
      /* Determine the point size of the glyph. */
      unsigned short  sw = (unsigned short)FT_MulDiv(
                             glyph->dwidth, 72000L,
                             (FT_Long)( font->point_size *
                                        font->resolution_x ) );


      if ( sw != glyph->swidth )
      {
        glyph->swidth = sw;

        if ( p->glyph_enc == -1 )
          _bdf_set_glyph_modified( font->umod,
                                   font->unencoded_used - 1 );
        else
          _bdf_set_glyph_modified( font->nmod, glyph->encoding );

        p->flags       |= _BDF_SWIDTH_ADJ;
        font->modified  = 1;
      }
    }

    p->flags |= _BDF_BBX;
    goto Exit;
  }

  /* And finally, gather up the bitmap. */
  if ( ft_memcmp( line, "BITMAP", 6 ) == 0 )
  {
    unsigned long  bitmap_size;


    if ( !( p->flags & _BDF_BBX ) )
    {
      /* Missing BBX field. */
      FT_ERROR(( "_bdf_parse_glyphs: " ERRMSG1, lineno, "BBX" ));
      error = BDF_Err_Missing_Bbx_Field;
      goto Exit;
    }

    /* Allocate enough space for the bitmap. */
    glyph->bpr = ( glyph->bbx.width * p->font->bpp + 7 ) >> 3;

    bitmap_size = glyph->bpr * glyph->bbx.height;
    if ( glyph->bpr > 0xFFFFU || bitmap_size > 0xFFFFU )
    {
      FT_ERROR(( "_bdf_parse_glyphs: " ERRMSG4, lineno ));
      error = BDF_Err_Bbx_Too_Big;
      goto Exit;
    }
    else
      glyph->bytes = (unsigned short)bitmap_size;

    if ( FT_NEW_ARRAY( glyph->bitmap, glyph->bytes ) )
      goto Exit;

    p->row    = 0;
    p->flags |= _BDF_BITMAP;

    goto Exit;
  }

  FT_ERROR(( "_bdf_parse_glyphs: " ERRMSG9, lineno ));
  error = BDF_Err_Invalid_File_Format;
  goto Exit;

Missing_Encoding:
  /* Missing ENCODING field. */
  FT_ERROR(( "_bdf_parse_glyphs: " ERRMSG1, lineno, "ENCODING" ));
  error = BDF_Err_Missing_Encoding_Field;

Exit:
  if ( error && ( p->flags & _BDF_GLYPH ) )
    FT_FREE( p->glyph_name );

  return error;
}

static int ext4_destroy_inline_data_nolock(handle_t *handle,
					   struct inode *inode)
{
	struct ext4_inode_info *ei = EXT4_I(inode);
	struct ext4_xattr_ibody_find is = {
		.s = { .not_found = 0, },
	};
	struct ext4_xattr_info i = {
		.name_index = EXT4_XATTR_INDEX_SYSTEM,
		.name = EXT4_XATTR_SYSTEM_DATA,
		.value = NULL,
		.value_len = 0,
	};
	int error;

	if (!ei->i_inline_off)
		return 0;

	error = ext4_get_inode_loc(inode, &is.iloc);
	if (error)
		return error;

	error = ext4_xattr_ibody_find(inode, &i, &is);
	if (error)
		goto out;

	BUFFER_TRACE(is.iloc.bh, "get_write_access");
	error = ext4_journal_get_write_access(handle, is.iloc.bh);
	if (error)
		goto out;

	error = ext4_xattr_ibody_inline_set(handle, inode, &i, &is);
	if (error)
		goto out;

	memset((void *)ext4_raw_inode(&is.iloc)->i_block,
		0, EXT4_MIN_INLINE_DATA_SIZE);

	if (ext4_has_feature_extents(inode->i_sb)) {
		if (S_ISDIR(inode->i_mode) ||
		    S_ISREG(inode->i_mode) || S_ISLNK(inode->i_mode)) {
			ext4_set_inode_flag(inode, EXT4_INODE_EXTENTS);
			ext4_ext_tree_init(handle, inode);
		}
	}
	ext4_clear_inode_flag(inode, EXT4_INODE_INLINE_DATA);

	get_bh(is.iloc.bh);
	error = ext4_mark_iloc_dirty(handle, inode, &is.iloc);

	EXT4_I(inode)->i_inline_off = 0;
	EXT4_I(inode)->i_inline_size = 0;
	ext4_clear_inode_state(inode, EXT4_STATE_MAY_INLINE_DATA);
out:
	brelse(is.iloc.bh);
	if (error == -ENODATA)
		error = 0;
	return error;
}

static unsigned long get_ctl_id_hash(const struct snd_ctl_elem_id *id)
{
	int i;
	unsigned long h;

	h = id->iface;
	h = MULTIPLIER * h + id->device;
	h = MULTIPLIER * h + id->subdevice;
	for (i = 0; id->name[i] && i < SNDRV_CTL_ELEM_ID_NAME_MAXLEN; i++)
		h = MULTIPLIER * h + id->name[i];
	h = MULTIPLIER * h + id->index;
	h &= LONG_MAX;
	return h;
}

static void  Ins_MIRP( INS_ARG )
{
  Int         point,
              cvtEntry;

  TT_F26Dot6  cvt_dist,
              distance,
              cur_dist,
              org_dist;

  point    = (Int)args[0];
  cvtEntry = (Int)args[1];

  /* XXX: UNDOCUMENTED! cvt[-1] = 0 always */

  if ( BOUNDS( args[0],   CUR.zp1.n_points ) ||
       BOUNDS( args[1]+1, CUR.cvtSize+1 )    )
  {
    CUR.error = TT_Err_Invalid_Reference;
    return;
  }

  if ( args[1] < 0 )
    cvt_dist = 0;
  else
    cvt_dist = CUR_Func_read_cvt( cvtEntry );

  /* single width test */

  if ( ABS( cvt_dist ) < CUR.GS.single_width_cutin )
  {
    if ( cvt_dist >= 0 )
      cvt_dist =  CUR.GS.single_width_value;
    else
      cvt_dist = -CUR.GS.single_width_value;
  }

  /* XXX : Undocumented - twilight zone */

  if ( CUR.GS.gep1 == 0 )
  {
    CUR.zp1.org_x[point] = CUR.zp0.org_x[CUR.GS.rp0] +
                           MulDiv_Round( cvt_dist,
                                         CUR.GS.freeVector.x,
                                         0x4000 );

    CUR.zp1.org_y[point] = CUR.zp0.org_y[CUR.GS.rp0] +
                           MulDiv_Round( cvt_dist,
                                         CUR.GS.freeVector.y,
                                         0x4000 );

    CUR.zp1.cur_x[point] = CUR.zp1.org_x[point];
    CUR.zp1.cur_y[point] = CUR.zp1.org_y[point];
  }

  org_dist = CUR_Func_dualproj( CUR.zp1.org_x[point] -
                                  CUR.zp0.org_x[CUR.GS.rp0],
                                CUR.zp1.org_y[point] -
                                  CUR.zp0.org_y[CUR.GS.rp0] );

  cur_dist = CUR_Func_project( CUR.zp1.cur_x[point] -
                                 CUR.zp0.cur_x[CUR.GS.rp0],
                               CUR.zp1.cur_y[point] -
                                 CUR.zp0.cur_y[CUR.GS.rp0] );

  /* auto-flip test */

  if ( CUR.GS.auto_flip )
  {
    if ( (org_dist ^ cvt_dist) < 0 )
      cvt_dist = -cvt_dist;
  }

  /* control value cutin and round */

  if ( (CUR.opcode & 4) != 0 )
  {
    /* XXX: Undocumented : only perform cut-in test when both points */
    /*      refer to the same zone.                                  */

    if ( CUR.GS.gep0 == CUR.GS.gep1 )
      if ( ABS( cvt_dist - org_dist ) >= CUR.GS.control_value_cutin )
        cvt_dist = org_dist;

    distance = CUR_Func_round( cvt_dist,
                               CUR.metrics.compensations[CUR.opcode & 3] );
  }
  else
    distance = Round_None( EXEC_ARGS
                           cvt_dist,
                           CUR.metrics.compensations[CUR.opcode & 3] );

  /* minimum distance test */

  if ( (CUR.opcode & 8) != 0 )
  {
    if ( org_dist >= 0 )
    {
      if ( distance < CUR.GS.minimum_distance )
        distance = CUR.GS.minimum_distance;
    }
    else
    {
      if ( distance > -CUR.GS.minimum_distance )
        distance = -CUR.GS.minimum_distance;
    }
  }

  CUR_Func_move( &CUR.zp1, point, distance - cur_dist );

  CUR.GS.rp1 = CUR.GS.rp0;

  if ( (CUR.opcode & 16) != 0 )
    CUR.GS.rp0 = point;

  /* UNDOCUMENTED! */

  CUR.GS.rp2 = point;
}

MagickExport const char *GetMagickProperty(ImageInfo *image_info,
  Image *image,const char *property,ExceptionInfo *exception)
{
  char
    value[MagickPathExtent];

  const char
    *string;

  assert(property[0] != '\0');
  assert(image != (Image *) NULL || image_info != (ImageInfo *) NULL );
  if (property[1] == '\0')  /* single letter property request */
    return(GetMagickPropertyLetter(image_info,image,*property,exception));
  if ((image != (Image *) NULL) && (image->debug != MagickFalse))
    (void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",image->filename);
  else
    if ((image_info != (ImageInfo *) NULL) &&
        (image_info->debug != MagickFalse))
    (void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s","no-images");
  *value='\0';           /* formated string */
  string=(char *) NULL;  /* constant string reference */
  switch (*property)
  {
    case 'b':
    {
      if (LocaleCompare("basename",property) == 0)
        {
          WarnNoImageReturn("\"%%[%s]\"",property);
          GetPathComponent(image->magick_filename,BasePath,value);
          if (*value == '\0')
            string="";
          break;
        }
      if (LocaleCompare("bit-depth",property) == 0)
        {
          (void) FormatLocaleString(value,MagickPathExtent,"%.20g",(double)
            GetImageDepth(image,exception));
          break;
        }
      break;
    }
    case 'c':
    {
      if (LocaleCompare("channels",property) == 0)
        {
          WarnNoImageReturn("\"%%[%s]\"",property);
          /* FUTURE: return actual image channels */
          (void) FormatLocaleString(value,MagickPathExtent,"%s",
            CommandOptionToMnemonic(MagickColorspaceOptions,(ssize_t)
            image->colorspace));
          LocaleLower(value);
          if( image->alpha_trait != UndefinedPixelTrait )
            (void) ConcatenateMagickString(value,"a",MagickPathExtent);
          break;
        }
      if (LocaleCompare("colorspace",property) == 0)
        {
          WarnNoImageReturn("\"%%[%s]\"",property);
          string=CommandOptionToMnemonic(MagickColorspaceOptions,(ssize_t)
            image->colorspace);
          break;
        }
      if (LocaleCompare("compose",property) == 0)
        {
          WarnNoImageReturn("\"%%[%s]\"",property);
          string=CommandOptionToMnemonic(MagickComposeOptions,(ssize_t)
            image->compose);
          break;
        }
      if (LocaleCompare("compression",property) == 0)
        {
          WarnNoImageReturn("\"%%[%s]\"",property);
          string=CommandOptionToMnemonic(MagickCompressOptions,(ssize_t)
            image->compression);
          break;
        }
      if (LocaleCompare("copyright",property) == 0)
        {
          (void) CopyMagickString(value,GetMagickCopyright(),MagickPathExtent);
          break;
        }
      break;
    }
    case 'd':
    {
      if (LocaleCompare("depth",property) == 0)
        {
          WarnNoImageReturn("\"%%[%s]\"",property);
          (void) FormatLocaleString(value,MagickPathExtent,"%.20g",(double)
            image->depth);
          break;
        }
      if (LocaleCompare("directory",property) == 0)
        {
          WarnNoImageReturn("\"%%[%s]\"",property);
          GetPathComponent(image->magick_filename,HeadPath,value);
          if (*value == '\0')
            string="";
          break;
        }
      break;
    }
    case 'e':
    {
      if (LocaleCompare("entropy",property) == 0)
        {
          double
            entropy;

          WarnNoImageReturn("\"%%[%s]\"",property);
          (void) GetImageEntropy(image,&entropy,exception);
          (void) FormatLocaleString(value,MagickPathExtent,"%.*g",
            GetMagickPrecision(),entropy);
          break;
        }
      if (LocaleCompare("extension",property) == 0)
        {
          WarnNoImageReturn("\"%%[%s]\"",property);
          GetPathComponent(image->magick_filename,ExtensionPath,value);
          if (*value == '\0')
            string="";
          break;
        }
      break;
    }
    case 'g':
    {
      if (LocaleCompare("gamma",property) == 0)
        {
          WarnNoImageReturn("\"%%[%s]\"",property);
          (void) FormatLocaleString(value,MagickPathExtent,"%.*g",
            GetMagickPrecision(),image->gamma);
          break;
        }
      break;
    }
    case 'h':
    {
      if (LocaleCompare("height",property) == 0)
        {
          WarnNoImageReturn("\"%%[%s]\"",property);
          (void) FormatLocaleString(value,MagickPathExtent,"%.20g",
            image->magick_rows != 0 ? (double) image->magick_rows : 256.0);
          break;
        }
      break;
    }
    case 'i':
    {
      if (LocaleCompare("input",property) == 0)
        {
          WarnNoImageReturn("\"%%[%s]\"",property);
          string=image->filename;
          break;
        }
      if (LocaleCompare("interlace",property) == 0)
        {
          string=CommandOptionToMnemonic(MagickInterlaceOptions,(ssize_t)
            image->interlace);
          break;
        }
      break;
    }
    case 'k':
    {
      if (LocaleCompare("kurtosis",property) == 0)
        {
          double
            kurtosis,
            skewness;

          WarnNoImageReturn("\"%%[%s]\"",property);
          (void) GetImageKurtosis(image,&kurtosis,&skewness,exception);
          (void) FormatLocaleString(value,MagickPathExtent,"%.*g",
            GetMagickPrecision(),kurtosis);
          break;
        }
      break;
    }
    case 'm':
    {
      if (LocaleCompare("magick",property) == 0)
        {
          WarnNoImageReturn("\"%%[%s]\"",property);
          string=image->magick;
          break;
        }
      if ((LocaleCompare("maxima",property) == 0) ||
          (LocaleCompare("max",property) == 0))
        {
          double
            maximum,
            minimum;

          WarnNoImageReturn("\"%%[%s]\"",property);
          (void) GetImageRange(image,&minimum,&maximum,exception);
          (void) FormatLocaleString(value,MagickPathExtent,"%.*g",
            GetMagickPrecision(),maximum);
          break;
        }
      if (LocaleCompare("mean",property) == 0)
        {
          double
            mean,
            standard_deviation;

          WarnNoImageReturn("\"%%[%s]\"",property);
          (void) GetImageMean(image,&mean,&standard_deviation,exception);
          (void) FormatLocaleString(value,MagickPathExtent,"%.*g",
            GetMagickPrecision(),mean);
          break;
        }
      if ((LocaleCompare("minima",property) == 0) ||
          (LocaleCompare("min",property) == 0))
        {
          double
            maximum,
            minimum;

          WarnNoImageReturn("\"%%[%s]\"",property);
          (void) GetImageRange(image,&minimum,&maximum,exception);
          (void) FormatLocaleString(value,MagickPathExtent,"%.*g",
            GetMagickPrecision(),minimum);
          break;
        }
      break;
    }
    case 'o':
    {
      if (LocaleCompare("opaque",property) == 0)
        {
          WarnNoImageReturn("\"%%[%s]\"",property);
          string=CommandOptionToMnemonic(MagickBooleanOptions,(ssize_t)
            IsImageOpaque(image,exception));
          break;
        }
      if (LocaleCompare("orientation",property) == 0)
        {
          WarnNoImageReturn("\"%%[%s]\"",property);
          string=CommandOptionToMnemonic(MagickOrientationOptions,(ssize_t)
            image->orientation);
          break;
        }
      if (LocaleCompare("output",property) == 0)
        {
          WarnNoImageInfoReturn("\"%%[%s]\"",property);
          (void) CopyMagickString(value,image_info->filename,MagickPathExtent);
          break;
        }
      break;
    }
    case 'p':
    {
      if (LocaleCompare("page",property) == 0)
        {
          WarnNoImageReturn("\"%%[%s]\"",property);
          (void) FormatLocaleString(value,MagickPathExtent,"%.20gx%.20g",
            (double) image->page.width,(double) image->page.height);
          break;
        }
#if defined(MAGICKCORE_LCMS_DELEGATE)
      if (LocaleCompare("profile:icc",property) == 0 ||
          LocaleCompare("profile:icm",property) == 0)
        {
#if !defined(LCMS_VERSION) || (LCMS_VERSION < 2000)
#define cmsUInt32Number  DWORD
#endif

          const StringInfo
            *profile;

          cmsHPROFILE
            icc_profile;

          profile=GetImageProfile(image,property+8);
          if (profile == (StringInfo *) NULL)
            break;
          icc_profile=cmsOpenProfileFromMem(GetStringInfoDatum(profile),
            (cmsUInt32Number) GetStringInfoLength(profile));
          if (icc_profile != (cmsHPROFILE *) NULL)
            {
#if defined(LCMS_VERSION) && (LCMS_VERSION < 2000)
              string=cmsTakeProductName(icc_profile);
#else
              (void) cmsGetProfileInfoASCII(icc_profile,cmsInfoDescription,
                "en","US",value,MagickPathExtent);
#endif
              (void) cmsCloseProfile(icc_profile);
            }
      }
#endif
      if (LocaleCompare("profiles",property) == 0)
        {
          const char
            *name;

          ResetImageProfileIterator(image);
          name=GetNextImageProfile(image);
          if (name != (char *) NULL)
            {
              (void) CopyMagickString(value,name,MagickPathExtent);
              name=GetNextImageProfile(image);
              while (name != (char *) NULL)
              {
                ConcatenateMagickString(value,",",MagickPathExtent);
                ConcatenateMagickString(value,name,MagickPathExtent);
                name=GetNextImageProfile(image);
              }
            }
          break;
        }
      break;
    }
    case 'q':
    {
      if (LocaleCompare("quality",property) == 0)
        {
          WarnNoImageReturn("\"%%[%s]\"",property);
          (void) FormatLocaleString(value,MagickPathExtent,"%.20g",(double)
            image->quality);
          break;
        }
      break;
    }
    case 'r':
    {
      if (LocaleCompare("resolution.x",property) == 0)
        {
          WarnNoImageReturn("\"%%[%s]\"",property);
          (void) FormatLocaleString(value,MagickPathExtent,"%g",
            image->resolution.x);
          break;
        }
      if (LocaleCompare("resolution.y",property) == 0)
        {
          WarnNoImageReturn("\"%%[%s]\"",property);
          (void) FormatLocaleString(value,MagickPathExtent,"%g",
            image->resolution.y);
          break;
        }
      break;
    }
    case 's':
    {
      if (LocaleCompare("scene",property) == 0)
        {
          WarnNoImageInfoReturn("\"%%[%s]\"",property);
          if (image_info->number_scenes != 0)
            (void) FormatLocaleString(value,MagickPathExtent,"%.20g",(double)
              image_info->scene);
          else {
            WarnNoImageReturn("\"%%[%s]\"",property);
            (void) FormatLocaleString(value,MagickPathExtent,"%.20g",(double)
              image->scene);
          }
          break;
        }
      if (LocaleCompare("scenes",property) == 0)
        {
          /* FUTURE: equivelent to %n? */
          WarnNoImageReturn("\"%%[%s]\"",property);
          (void) FormatLocaleString(value,MagickPathExtent,"%.20g",(double)
            GetImageListLength(image));
          break;
        }
      if (LocaleCompare("size",property) == 0)
        {
          WarnNoImageReturn("\"%%[%s]\"",property);
          (void) FormatMagickSize(GetBlobSize(image),MagickFalse,"B",
            MagickPathExtent,value);
          break;
        }
      if (LocaleCompare("skewness",property) == 0)
        {
          double
            kurtosis,
            skewness;

          WarnNoImageReturn("\"%%[%s]\"",property);
          (void) GetImageKurtosis(image,&kurtosis,&skewness,exception);
          (void) FormatLocaleString(value,MagickPathExtent,"%.*g",
            GetMagickPrecision(),skewness);
          break;
        }
      if (LocaleCompare("standard-deviation",property) == 0)
        {
          double
            mean,
            standard_deviation;

          WarnNoImageReturn("\"%%[%s]\"",property);
          (void) GetImageMean(image,&mean,&standard_deviation,exception);
          (void) FormatLocaleString(value,MagickPathExtent,"%.*g",
            GetMagickPrecision(),standard_deviation);
          break;
        }
      break;
    }
    case 't':
    {
      if (LocaleCompare("type",property) == 0)
        {
          WarnNoImageReturn("\"%%[%s]\"",property);
          string=CommandOptionToMnemonic(MagickTypeOptions,(ssize_t)
            IdentifyImageType(image,exception));
          break;
        }
       break;
    }
    case 'u':
    {
      if (LocaleCompare("unique",property) == 0)
        {
          WarnNoImageInfoReturn("\"%%[%s]\"",property);
          string=image_info->unique;
          break;
        }
      if (LocaleCompare("units",property) == 0)
        {
          WarnNoImageReturn("\"%%[%s]\"",property);
          string=CommandOptionToMnemonic(MagickResolutionOptions,(ssize_t)
            image->units);
          break;
        }
      break;
    }
    case 'v':
    {
      if (LocaleCompare("version",property) == 0)
        {
          string=GetMagickVersion((size_t *) NULL);
          break;
        }
      break;
    }
    case 'w':
    {
      if (LocaleCompare("width",property) == 0)
        {
          WarnNoImageReturn("\"%%[%s]\"",property);
          (void) FormatLocaleString(value,MagickPathExtent,"%.20g",(double)
            (image->magick_columns != 0 ? image->magick_columns : 256));
          break;
        }
      break;
    }
  }
  if (string != (char *) NULL)
    return(string);
  if (*value != '\0')
    {
      /*
        Create a cloned copy of result, that will get cleaned up, eventually.
      */
      if (image != (Image *) NULL)
        {
          (void) SetImageArtifact(image,"get-property",value);
          return(GetImageArtifact(image,"get-property"));
        }
      else
        {
          (void) SetImageOption(image_info,"get-property",value);
          return(GetImageOption(image_info,"get-property"));
        }
    }
  return((char *) NULL);
}

