void Compute(OpKernelContext* context) override {
  const Tensor* reverse_index_map_t;
  const Tensor* grad_values_t;
  OP_REQUIRES_OK(context,
                 context->input("reverse_index_map", &reverse_index_map_t));
  OP_REQUIRES_OK(context, context->input("grad_values", &grad_values_t));

  const CPUDevice& d = context->eigen_device<CPUDevice>();

  OP_REQUIRES(
      context, TensorShapeUtils::IsVector(reverse_index_map_t->shape()),
      errors::InvalidArgument("reverse_index_map must be a vector, saw: ",
                              reverse_index_map_t->shape().DebugString()));

  const auto reverse_index_map = reverse_index_map_t->vec<int64>();
  const auto grad_values = grad_values_t->vec<T>();

  const int64 N = reverse_index_map_t->shape().dim_size(0);
  const int64 N_full = grad_values_t->shape().dim_size(0);

  Tensor* d_values_t;
  OP_REQUIRES_OK(context, context->allocate_output(
                              "d_values", TensorShape({N}), &d_values_t));
  auto d_values = d_values_t->vec<T>();
  Tensor* d_default_value_t;
  OP_REQUIRES_OK(context,
                 context->allocate_output("d_default_value", TensorShape({}),
                                          &d_default_value_t));
  T& d_default_value = d_default_value_t->scalar<T>()();
  d_default_value = T();

  Tensor visited_t;
  OP_REQUIRES_OK(context, context->allocate_temp(
                              DT_BOOL, TensorShape({N_full}), &visited_t));
  auto visited = visited_t.vec<bool>();
  visited.device(d) = visited.constant(false);

  for (int i = 0; i < N; ++i) {
    // Locate the index of the output of the forward prop associated
    // with this location in the input of the forward prop.  Copy
    // the gradient into it.  Mark it as visited.
    d_values(i) = grad_values(reverse_index_map(i));
    visited(reverse_index_map(i)) = true;
  }
  for (int j = 0; j < N_full; ++j) {
    // The default value gradient gets the accumulated remainder of
    // the backprop values (since the default value was used to fill
    // in these slots in the forward calculation).
    if (!visited(j)) {
      d_default_value += grad_values(j);
    }
  }
}

rdpdr_process(STREAM s)
{
	uint32 handle;
 	uint16 vmin;
 	uint16 component;
 	uint16 pakid;

 	logger(Protocol, Debug, "rdpdr_process()");
 	/* hexdump(s->p, s->end - s->p); */

	in_uint16(s, component);
	in_uint16(s, pakid);

	if (component == RDPDR_CTYP_CORE)
	{
		switch (pakid)
		{
			case PAKID_CORE_DEVICE_IOREQUEST:
				rdpdr_process_irp(s);
				break;

			case PAKID_CORE_SERVER_ANNOUNCE:
 				/* DR_CORE_SERVER_ANNOUNCE_REQ */
 				in_uint8s(s, 2);	/* skip versionMajor */
 				in_uint16_le(s, vmin);	/* VersionMinor */
 				in_uint32_le(s, g_client_id);	/* ClientID */

 				/* The RDP client is responsibility to provide a random client id
 				   if server version is < 12 */
 				if (vmin < 0x000c)
					g_client_id = 0x815ed39d;	/* IP address (use 127.0.0.1) 0x815ed39d */
				g_epoch++;

#if WITH_SCARD
				/*
				 * We need to release all SCARD contexts to end all
				 * current transactions and pending calls
				 */
				scard_release_all_contexts();

				/*
				 * According to [MS-RDPEFS] 3.2.5.1.2:
				 *
				 * If this packet appears after a sequence of other packets,
				 * it is a signal that the server has reconnected to a new session
				 * and the whole sequence has been reset. The client MUST treat
				 * this packet as the beginning of a new sequence.
				 * The client MUST also cancel all outstanding requests and release
				 * previous references to all devices.
				 *
				 * If any problem arises in the future, please, pay attention to the
				 * "If this packet appears after a sequence of other packets" part
				 *
				 */

#endif

				rdpdr_send_client_announce_reply();
				rdpdr_send_client_name_request();
				break;

			case PAKID_CORE_CLIENTID_CONFIRM:
				rdpdr_send_client_device_list_announce();
				break;

			case PAKID_CORE_DEVICE_REPLY:
				in_uint32(s, handle);
				logger(Protocol, Debug,
				       "rdpdr_process(), server connected to resource %d", handle);
				break;

			case PAKID_CORE_SERVER_CAPABILITY:
				rdpdr_send_client_capability_response();
				break;

			default:
				logger(Protocol, Debug,
				       "rdpdr_process(), pakid 0x%x of component 0x%x", pakid,
				       component);
				break;

		}
	}
	else if (component == RDPDR_CTYP_PRN)
	{
		if (pakid == PAKID_PRN_CACHE_DATA)
			printercache_process(s);
	}
	else
		logger(Protocol, Warning, "rdpdr_process(), unhandled component 0x%x", component);
}

