static int hash_accept(struct socket *sock, struct socket *newsock, int flags)
{
	struct sock *sk = sock->sk;
	struct alg_sock *ask = alg_sk(sk);
	struct hash_ctx *ctx = ask->private;
	struct ahash_request *req = &ctx->req;
	char state[crypto_ahash_statesize(crypto_ahash_reqtfm(req))];
 	struct sock *sk2;
 	struct alg_sock *ask2;
 	struct hash_ctx *ctx2;
 	int err;

	err = crypto_ahash_export(req, state);
 	if (err)
 		return err;

	err = af_alg_accept(ask->parent, newsock);
	if (err)
		return err;

 	sk2 = newsock->sk;
 	ask2 = alg_sk(sk2);
 	ctx2 = ask2->private;
	ctx2->more = 1;

 	err = crypto_ahash_import(&ctx2->req, state);
 	if (err) {
		sock_orphan(sk2);
		sock_put(sk2);
	}

	return err;
}

int lazy_bdecode(char const* start, char const* end, lazy_entry& ret
	, error_code& ec, int* error_pos, int depth_limit, int item_limit)
{
	char const* const orig_start = start;
	ret.clear();
	if (start == end) return 0;

	std::vector<lazy_entry*> stack;

	stack.push_back(&ret);
	while (start < end)
	{
		if (stack.empty()) break; // done!

		lazy_entry* top = stack.back();

		if (int(stack.size()) > depth_limit) TORRENT_FAIL_BDECODE(bdecode_errors::depth_exceeded);
		if (start >= end) TORRENT_FAIL_BDECODE(bdecode_errors::unexpected_eof);
		char t = *start;
		++start;
		if (start >= end && t != 'e') TORRENT_FAIL_BDECODE(bdecode_errors::unexpected_eof);

		switch (top->type())
		{
			case lazy_entry::dict_t:
			{
				if (t == 'e')
				{
					top->set_end(start);
					stack.pop_back();
					continue;
				}
				if (!is_digit(t)) TORRENT_FAIL_BDECODE(bdecode_errors::expected_string);
				boost::int64_t len = t - '0';
				start = parse_int(start, end, ':', len);
				if (start == 0 || start + len + 3 > end || *start != ':')
					TORRENT_FAIL_BDECODE(bdecode_errors::expected_colon);
				++start;
				if (start == end) TORRENT_FAIL_BDECODE(bdecode_errors::unexpected_eof);
				lazy_entry* ent = top->dict_append(start);
				if (ent == 0) TORRENT_FAIL_BDECODE(boost::system::errc::not_enough_memory);
				start += len;
				if (start >= end) TORRENT_FAIL_BDECODE(bdecode_errors::unexpected_eof);
				stack.push_back(ent);
				t = *start;
				++start;
				break;
			}
			case lazy_entry::list_t:
			{
				if (t == 'e')
				{
					top->set_end(start);
					stack.pop_back();
					continue;
				}
				lazy_entry* ent = top->list_append();
				if (ent == 0) TORRENT_FAIL_BDECODE(boost::system::errc::not_enough_memory);
				stack.push_back(ent);
				break;
			}
			default: break;
		}

		--item_limit;
		if (item_limit <= 0) TORRENT_FAIL_BDECODE(bdecode_errors::limit_exceeded);

		top = stack.back();
		switch (t)
		{
			case 'd':
				top->construct_dict(start - 1);
				continue;
			case 'l':
				top->construct_list(start - 1);
				continue;
			case 'i':
			{
				char const* int_start = start;
				start = find_char(start, end, 'e');
				top->construct_int(int_start, start - int_start);
				if (start == end) TORRENT_FAIL_BDECODE(bdecode_errors::unexpected_eof);
				TORRENT_ASSERT(*start == 'e');
				++start;
				stack.pop_back();
				continue;
			}
			default:
			{
				if (!is_digit(t))
					TORRENT_FAIL_BDECODE(bdecode_errors::expected_value);

				boost::int64_t len = t - '0';
				start = parse_int(start, end, ':', len);
				if (start == 0 || start + len + 1 > end || *start != ':')
					TORRENT_FAIL_BDECODE(bdecode_errors::expected_colon);
				++start;
				top->construct_string(start, int(len));
				stack.pop_back();
				start += len;
				continue;
			}
		}
		return 0;
	}
	return 0;
}

static int jp2_getcs(jp2_colr_t *colr)
{
	if (colr->method == JP2_COLR_ENUM) {
		switch (colr->csid) {
		case JP2_COLR_SRGB:
			return JAS_CLRSPC_SRGB;
			break;
		case JP2_COLR_SYCC:
			return JAS_CLRSPC_SYCBCR;
			break;
		case JP2_COLR_SGRAY:
			return JAS_CLRSPC_SGRAY;
			break;
		}
	}
	return JAS_CLRSPC_UNKNOWN;
}

static int calc_max_log2_tile_cols(int Sb64Cols) {
	int maxLog2 = 1;
	while ((Sb64Cols >> maxLog2) >= VP9_MIN_TILE_WIDTH_B64)
		maxLog2++;

	return maxLog2 - 1;
}

call_qftf_func(qf_list_T *qfl, int qf_winid, long start_idx, long end_idx)
{
    callback_T	*cb = &qftf_cb;
    list_T	*qftf_list = NULL;

    // If 'quickfixtextfunc' is set, then use the user-supplied function to get
    // the text to display. Use the local value of 'quickfixtextfunc' if it is
    // set.
    if (qfl->qf_qftf_cb.cb_name != NULL)
	cb = &qfl->qf_qftf_cb;
    if (cb->cb_name != NULL)
    {
	typval_T	args[1];
	dict_T		*d;
	typval_T	rettv;

	// create the dict argument
	if ((d = dict_alloc_lock(VAR_FIXED)) == NULL)
	    return NULL;
	dict_add_number(d, "quickfix", (long)IS_QF_LIST(qfl));
	dict_add_number(d, "winid", (long)qf_winid);
	dict_add_number(d, "id", (long)qfl->qf_id);
	dict_add_number(d, "start_idx", start_idx);
	dict_add_number(d, "end_idx", end_idx);
	++d->dv_refcount;
	args[0].v_type = VAR_DICT;
	args[0].vval.v_dict = d;

	qftf_list = NULL;
	if (call_callback(cb, 0, &rettv, 1, args) != FAIL)
	{
	    if (rettv.v_type == VAR_LIST)
	    {
		qftf_list = rettv.vval.v_list;
		qftf_list->lv_refcount++;
	    }
	    clear_tv(&rettv);
	}
	dict_unref(d);
    }

    return qftf_list;
}

